/**
 * The API on its own, for production: `node --experimental-strip-types server/standalone.ts` behind the load
 * balancer. The 21:00 batch, the day rollovers and the reminders also run from here on a one-minute timer
 * (pg-boss in the architecture; see docs/deviations.md).
 */
import { createServer } from 'node:http';
import { app } from './app';
import { loadDb } from './store';
import { tick } from './domain/jobs';

const port = Number(process.env.PORT ?? 8787);

createServer(async (req, res) => {
  const url = `http://${req.headers.host ?? 'localhost'}${req.url}`;
  const chunks: Buffer[] = [];
  for await (const chunk of req) chunks.push(chunk as Buffer);
  const body = chunks.length ? Buffer.concat(chunks) : undefined;
  const response = await app.fetch(new Request(url, { method: req.method, headers: req.headers as Record<string, string>, body: req.method === 'GET' || req.method === 'HEAD' ? undefined : body }));
  res.writeHead(response.status, Object.fromEntries(response.headers.entries()));
  res.end(Buffer.from(await response.arrayBuffer()));
}).listen(port, '0.0.0.0');

setInterval(async () => tick(await loadDb()), 60_000);
