/**
 * Theme colours for the few things drawn outside the class names (SVG strokes and fills). On the web they are
 * the theme's CSS variables, so light and dark follow the stylesheet; on iOS and Android they are the same
 * colours converted once to sRGB (scripts/theme-colors.mjs).
 */
import { Platform, useColorScheme } from 'react-native';
import { nativeColors } from './native-colors';

export type Token = keyof typeof nativeColors.light;

export function useTokenColor(): (token: Token) => string {
  const scheme = useColorScheme() === 'dark' ? 'dark' : 'light';
  return (token) => (Platform.OS === 'web' ? `var(--sz-${token})` : nativeColors[scheme][token]);
}

/** SVG paint as props: inline style on the web (where variables resolve), plain attributes on native. */
export function usePaint(): (p: { fill?: Token; stroke?: Token }) => Record<string, unknown> {
  const color = useTokenColor();
  return ({ fill, stroke }) => {
    if (Platform.OS === 'web') return { style: { ...(fill ? { fill: color(fill) } : { fill: 'none' }), ...(stroke ? { stroke: color(stroke) } : {}) } };
    return { fill: fill ? color(fill) : 'none', ...(stroke ? { stroke: color(stroke) } : {}) };
  };
}
