/** The last seven days' average, for M-01's '건강 앱에서 가져오기'. */
export async function readUsualSteps(): Promise<number | null> {
  if (!(await linkHealth())) return null;
  const end = new Date();
  end.setHours(0, 0, 0, 0);
  const start = new Date(end.getTime() - 7 * 86400000);
  const r = await readSteps(start.getTime(), end.getTime());
  return r ? Math.round(r.steps / 7) : null;
}
