13:export function track(name: string, props?: Props): void {
/**
 * The app's one door for analytics (architecture §12). Score and matching events are written by the server
 * where they happen; the device sends what only it sees (a blocked intake, a sheet opened, a screen shown).
 * Events are batched to POST /v1/events. Weight values never go in an event.
 */
import { api } from './api';
import { now } from './clock';

type Props = Record<string, string | number | boolean | null>;
let queue: { name: string; at: string; props?: Props }[] = [];
let timer: ReturnType<typeof setTimeout> | null = null;

export function track(name: string, props?: Props): void {
  const clean = props ? Object.fromEntries(Object.entries(props).filter(([k]) => !/kg/i.test(k))) : undefined;
  queue.push({ name, at: new Date(now()).toISOString(), props: clean });
  if (queue.length >= 20) void flush();
  else if (!timer) timer = setTimeout(() => void flush(), 5000);
}

export async function flush(): Promise<void> {
  if (timer) clearTimeout(timer);
  timer = null;
  if (!queue.length) return;
  const batch = queue.slice(0, 50);
  queue = queue.slice(50);
  try {
    await api('POST', '/v1/events', { events: batch });
  } catch {
    // Analytics never gets in the way: a lost batch is dropped, not retried at the cost of a record.
  }
}

